-- aud.change_canonical: The fixed text a change-log row is hashed over (KRN-AUD-03, ruling Q2): every column but the hashes, each as <octet length>:<text>; (null as ~;). The verifier rebuilds the same text.
create or replace function aud.change_canonical(
    p_id uuid, p_occurred_at timestamptz, p_actor_user_id uuid, p_actor_kind text, p_entity_type text, p_entity_id uuid,
    p_company_id uuid, p_action text, p_changes jsonb, p_subject_person_id uuid, p_correlation_id uuid, p_ip_address inet,
    p_source text, p_created_at timestamptz, p_created_by uuid)
returns text
language sql immutable parallel safe
set search_path = pg_catalog, pg_temp
as $fn$
    select string_agg(case when v is null then '~;' else octet_length(v)::text || ':' || v || ';' end, '' order by n)
    from unnest(array[
        p_id::text,
        to_char(p_occurred_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
        p_actor_user_id::text, p_actor_kind, p_entity_type, p_entity_id::text, p_company_id::text, p_action,
        p_changes::text, p_subject_person_id::text, p_correlation_id::text, p_ip_address::text, p_source,
        to_char(p_created_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
        p_created_by::text]) with ordinality as t(v, n)
$fn$;
revoke all on function aud.change_canonical(uuid, timestamptz, uuid, text, text, uuid, uuid, text, jsonb, uuid, uuid, inet, text, timestamptz, uuid) from public;
grant execute on function aud.change_canonical(uuid, timestamptz, uuid, text, text, uuid, uuid, text, jsonb, uuid, uuid, inet, text, timestamptz, uuid) to app_rw, app_ro, app_audit;

-- aud.append_changes: The only way rows enter aud.change_log (KRN-AUD-01, KRN-AUD-03; rulings Q1, Q2, P1, P2): owned by the database owner, run with its rights; the caller cannot choose hashes, order or anchors. One chain per customer database, written under a transaction-level lock; occurred_at never goes backwards along the chain (a row earlier than the head moves to one microsecond after it), so a date range is one contiguous piece; each day's last hash is kept in aud.chain_anchors.
create or replace function aud.append_changes(p_entries jsonb)
returns integer
language plpgsql security definer
set search_path = pg_catalog, pg_temp
as $fn$
declare
    e jsonb;
    head_day date;
    head_at timestamptz;
    head_hash bytea;
    at timestamptz;
    hash bytea;
    written integer := 0;
begin
    if p_entries is null or jsonb_typeof(p_entries) <> 'array' then
        raise exception 'aud.append_changes expects a json array' using errcode = '22023';
    end if;

    perform pg_advisory_xact_lock(hashtext('aud.change_log.chain'));
    -- The head is the latest row; the latest anchored day bounds the search to its partition (index ix_change_log_occurred_at, CR-029).
    select max(a.day) into head_day from aud.chain_anchors a;
    if head_day is not null then
        select c.occurred_at, c.row_hash into head_at, head_hash from aud.change_log c
        where c.occurred_at >= (head_day::timestamp at time zone 'UTC') order by c.occurred_at desc limit 1;
    end if;
    if head_hash is null then
        head_hash := decode(repeat('00', 32), 'hex');
    end if;

    for e in select value from jsonb_array_elements(p_entries) loop
        at := (e ->> 'occurred_at')::timestamptz;
        if at is null then
            raise exception 'aud.append_changes: occurred_at is required' using errcode = '23502';
        end if;
        if head_at is not null and at <= head_at then
            at := head_at + interval '1 microsecond';
        end if;

        hash := sha256(head_hash || convert_to(aud.change_canonical(
            (e ->> 'id')::uuid, at, (e ->> 'actor_user_id')::uuid, e ->> 'actor_kind', e ->> 'entity_type', (e ->> 'entity_id')::uuid,
            (e ->> 'company_id')::uuid, e ->> 'action', e -> 'changes', (e ->> 'subject_person_id')::uuid, (e ->> 'correlation_id')::uuid,
            (e ->> 'ip_address')::inet, e ->> 'source', at, (e ->> 'created_by')::uuid), 'UTF8'));

        insert into aud.change_log (id, occurred_at, actor_user_id, actor_kind, entity_type, entity_id, company_id, action, changes,
                                    subject_person_id, correlation_id, ip_address, prev_hash, row_hash, created_at, created_by, source)
        values ((e ->> 'id')::uuid, at, (e ->> 'actor_user_id')::uuid, e ->> 'actor_kind', e ->> 'entity_type', (e ->> 'entity_id')::uuid,
                (e ->> 'company_id')::uuid, e ->> 'action', e -> 'changes', (e ->> 'subject_person_id')::uuid, (e ->> 'correlation_id')::uuid,
                (e ->> 'ip_address')::inet, head_hash, hash, at, (e ->> 'created_by')::uuid, e ->> 'source');

        insert into aud.chain_anchors (day, last_hash, verified_at) values ((at at time zone 'UTC')::date, hash, null)
        on conflict (day) do update set last_hash = excluded.last_hash, verified_at = null;

        head_at := at;
        head_hash := hash;
        written := written + 1;
    end loop;

    return written;
end
$fn$;
revoke all on function aud.append_changes(jsonb) from public;
grant execute on function aud.append_changes(jsonb) to app_rw;

-- aud.mark_anchor_verified: Records that the verifier checked a finished day's anchor (KRN-AUD-03); the only change allowed to aud.chain_anchors besides appends.
create or replace function aud.mark_anchor_verified(p_day date, p_last_hash bytea, p_at timestamptz)
returns boolean
language plpgsql security definer
set search_path = pg_catalog, pg_temp
as $fn$
begin
    update aud.chain_anchors set verified_at = p_at where day = p_day and last_hash = p_last_hash;
    return found;
end
$fn$;
revoke all on function aud.mark_anchor_verified(date, bytea, timestamptz) from public;
grant execute on function aud.mark_anchor_verified(date, bytea, timestamptz) to app_rw;

