-- aud.ensure_subject_key: The data subject's audit key (spec 03 R-21): stores the offered wrapped key when the person has none and returns the stored one, and whether it was destroyed.
create or replace function aud.ensure_subject_key(p_person_id uuid, p_wrapped_key bytea)
returns table (wrapped_key bytea, destroyed boolean)
language plpgsql security definer
set search_path = pg_catalog, pg_temp
as $fn$
begin
    insert into aud.subject_keys (person_id, wrapped_key, destroyed_at) values (p_person_id, p_wrapped_key, null)
    on conflict (person_id) do nothing;
    return query select k.wrapped_key, k.destroyed_at is not null from aud.subject_keys k where k.person_id = p_person_id;
end
$fn$;
revoke all on function aud.ensure_subject_key(uuid, bytea) from public;
grant execute on function aud.ensure_subject_key(uuid, bytea) to app_rw;

-- aud.destroy_subject_key: Destroys a data subject's audit key (spec 03 R-21; used by retention and erasure, HRM-PRV-04, ADM-SEC-06): the key bytes are overwritten, so that person's personal values in the log become unreadable while every hash stays valid. A person without a key gets a destroyed entry, so no new key is ever made for them.
create or replace function aud.destroy_subject_key(p_person_id uuid, p_at timestamptz)
returns boolean
language plpgsql security definer
set search_path = pg_catalog, pg_temp
as $fn$
begin
    insert into aud.subject_keys (person_id, wrapped_key, destroyed_at) values (p_person_id, '\x'::bytea, p_at)
    on conflict (person_id) do update set wrapped_key = '\x'::bytea, destroyed_at = p_at where aud.subject_keys.destroyed_at is null;
    return found;
end
$fn$;
revoke all on function aud.destroy_subject_key(uuid, timestamptz) from public;
grant execute on function aud.destroy_subject_key(uuid, timestamptz) to app_rw;
